# Try hypothesis: each pixel projects diagonally in 4 directions
# For each (r,c) with value v, add new positions going in 8 diagonal directions
def project_grid(grid_in, H, W):
    """Project each pixel in 4 main diagonal directions"""
    import copy
    grid_out = [row[:] for row in grid_in]

    # Find all special pixels (non-background)
    background = 7
    special_pixels = []
    for r in range(H):
        for c in range(W):
            if grid_in[r][c] != background:
                special_pixels.append((r, c, grid_in[r][c]))

    for r, c, val in special_pixels:
        # Project in 4 directions (up-left, up-right, down-left, down-right)
        for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
            nr, nc = r + dr, c + dc
            while 0 <= nr < H and 0 <= nc < W:
                # Stop after first projection to avoid double-counting
                if grid_out[nr][nc] == background:
                    grid_out[nr][nc] = val
                    nr += dr
                    nc += dc
                else:
                    break

    return grid_out

